    def knapsack(weights: List[int], values: List[int], capacity: int) -> Tuple[bool, int, List[int]]:
        n = len(weights)
        dp = [[0] * (capacity + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for w in range(capacity + 1):
                if weights[i-1] <= w:
                    dp[i][w] = max(dp[i-1][w], dp[i-1][w-weights[i-1]] + values[i-1])
                else:
                    dp[i][w] = dp[i-1][w]

        total_value = dp[n][capacity]
        if total_value == 0:
            return False, 0, []

        selected_items = []
        w = capacity
        for i in range(n, 0, -1):
            if dp[i][w] != dp[i-1][w]:
                selected_items.append(i-1)
                w -= weights[i-1]
        selected_items.reverse()
        return True, total_value, selected_items

    weights = [1, 4, 3, 5, 4]
    values = [5, 1, 5, 5, 4]
    capacity = 25
    return knapsack(weights, values, capacity)
