def solution():
    # Importing necessary libraries
    from pulp import LpProblem, LpVariable, LpMinimize, LpBinary, lpSum

    # Define the graph edges
    edges = [(1, 6), (2, 3), (2, 8), (3, 7), (4, 8), (6, 7), (7, 8)]

    # Define the number of vertices and colors
    num_vertices = 8
    num_colors = 2
    colors = [chr(ord('A') + i) for i in range(num_colors)]

    # Create the problem
    problem = LpProblem('GraphColoring', LpMinimize)

    # Create variables for vertex colors
    vertex_colors = {}
    for v in range(1, num_vertices + 1):
        vertex_colors[v] = {}
        for c in range(num_colors):
            vertex_colors[v][c] = LpVariable(f'color_{v}_{colors[c]}', cat=LpBinary)

    # Each vertex must have exactly one color
    for v in range(1, num_vertices + 1):
